//! Text decorations (phase-5.md item 5.16): which lines affect a box's
//! text, and where each is drawn.
//!
//! Source: CSS 2.1 §16.3.1 ("When specified on or propagated to an inline
//! element, it affects all the boxes generated by that element"; "For block
//! containers that establish an inline formatting context, the decorations
//! are propagated to an anonymous inline element that wraps all the in-flow
//! inline-level children of the block container. For all other elements it
//! is propagated to any in-flow children. Note that text decorations are
//! not propagated to … the contents of atomic inline-level descendants such
//! as inline blocks and inline tables"); the Quirks Mode Standard (commit
//! `5a06deb5`) §3.11 ("In quirks mode, text decoration must not propagate
//! into table elements").
//!
//! Modelling choices: `mod.rs`'s "Text decorations".

use clazel_style::cascade::computed::DecorationLines;

use super::state::{Decor, Line};
use crate::flow::FontMetrics;
use crate::flow::fragment::Rect;
use crate::flow::length::half_down;

/// The decorations of a box whose parent's are `parent`, whose own
/// `text-decoration-line` is `own` in colour `colour`, and which starts
/// afresh when `cut` (an atomic inline, or a table in quirks mode)
/// (`state.rs`'s contract).
pub fn propagate(parent: Decor, own: DecorationLines, colour: [u8; 4], cut: bool) -> Decor {
    let mut d = if cut { Decor::default() } else { parent };
    if own.underline {
        d.underline = Some(colour);
    }
    if own.overline {
        d.overline = Some(colour);
    }
    if own.line_through {
        d.line_through = Some(colour);
    }
    d
}

/// The rectangle of decoration line `kind` under, over or through a run
/// from `x` that is `width` wide on baseline `baseline`, in a font with
/// metrics `m`, in 1/64 CSS px (`state.rs`'s contract).
pub fn line_rect(kind: Line, baseline: i32, m: &FontMetrics, x: i32, width: i32) -> Rect {
    let t = m.underline_thickness.max(1);
    let y = match kind {
        // `post`'s underline position: its top, below the baseline.
        Line::Underline => baseline.saturating_add(m.underline_position),
        // The top of the run's ascent.
        Line::Overline => baseline.saturating_sub(m.ascent),
        // Centred half the x-height above the baseline.
        Line::LineThrough => baseline
            .saturating_sub(half_down(m.x_height))
            .saturating_sub(half_down(t)),
    };
    Rect {
        x,
        y,
        width: width.max(0),
        height: t,
    }
}
